-- «KURATORGA SAVOL» assistant knowledge base (support_kb was empty since #302). Owner, 2026-10-11: "yes add FAQs to db".
-- Source: every curator answer in the four 6.0 groups and the 5.0 / 4.0 groups over 30 days (1,307 text answers →
-- 47 entries), then checked against the live platform (rating rule 10-08, button labels, 6 modules, resubmit button
-- «Qayta yuklash», video homework → group topic) and against official pricing/help pages as of 2026-10-11
-- (ChatGPT, Higgsfield, Syntx, Claude, Midjourney, Google AI / Flow). Wrong or unverifiable sentences were rewritten
-- or removed (e.g. ChatGPT has no annual plan for individuals; Flow = 50 free credits/day; the 8,000-character
-- instructions cap is unverified; Humo/Uzcard acceptance is unverified → "xalqaro karta").
--   approved 33: the assistant may answer with them (verbatim; still shadow mode → a curator taps ✅ first)
--   draft    11: contradictory or 5.0-only — stored for the owner, never sent (assistant reads status='approved')
--   retired  3: extra tasks / Instagram, switched off on 10-08
-- Replay-safe: on conflict do nothing (an owner's later edit or status change is never overwritten).

insert into public.support_kb (id, category, title_uz, example_questions, answer_html, links, status, volatile)
values
  ($kb$new-student-where-to-start$kb$, $kb$course_logistics$kb$, $kb$Kursga yangi qoʻshildim — nimadan boshlayman?$kb$,
   array[$kb$#savol Assalomu alekum kecha qöshildim challenge ga nimadan boshlashim kere chunmayabman$kb$, $kb$Assalom aleykum men gurxda yangiman kimdr tushuncha beraoladimi dars qayerdan boshlanadi yozishmalar kopligiga hamma narsa chalkash yoki men tushunmayapman$kb$, $kb$#savol Ассалому алейкум. Мен ссылка буйича энди кушилдим. Дарсларни каердан нимадан бошлаш керак? Айтиб юбороласизларми$kb$, $kb$#savol Assalomu alaykum men gruppaga bugun qo'shildim o'tgan dars nimalar o'tilgan va vazifalar nima bo'lgan menga kimdir qisqacha javob berolidimi?$kb$, $kb$#savol Man kecha yangi qoshildim ma'lumotlar juda ko'pde tuyulvoti va bulani qando eslab qolish kere va esmdan chiqib qosachi dib hovotir bor.$kb$]::text[],
   $kb$Xush kelibsiz! Avval guruhdagi «MUHIM EʼLONLAR» boʻlimini oʻqib chiqing: u yerda tartib-qoidalar va guruhdan qanday foydalanish boʻyicha video qoʻllanma bor. Darslarni botdagi «🚀 Ilovani ochish» tugmasi orqali platformada koʻring — reyting ballari platformada koʻrilgan darslar va topshirilgan uyga vazifalar uchun beriladi. Har bir modul darslarini koʻrib boʻlgach, uyga vazifani topshirasiz. Tushunmagan joyingizni «KURATORGA SAVOL» boʻlimida «#savol» deb yozib soʻrang.$kb$,
   '{}'::text[], $kb$approved$kb$, false),
  ($kb$where-to-watch-lessons$kb$, $kb$platform_usage$kb$, $kb$Darslarni qayerdan koʻraman? Darsliklar kanali qayerda?$kb$,
   array[$kb$Kechirasizlar darsliklarni qayerda ko'raayapsizlar$kb$, $kb$#savol асосий дарслар каналини линкини ташаворолисми топомаяман$kb$, $kb$Uyga vazifani kórish uchun botni linkini tashab yuboringlar iltimos.$kb$, $kb$#savol darslikdagi vidiolar qancha vaqtgacha oʻzimizda koʻrinib turadi yani kurs tugagach ham oʻz ustimizda ishlash uchun$kb$, $kb$#savol guruhlarimiz 5 haftadan keyin uchiruladimi yoki uzimizda qoladimi dars tugagandan keyin$kb$]::text[],
   $kb$Darslarni botdagi «🚀 Ilovani ochish» tugmasi orqali platformada yoki «Darsliklar» Telegram kanalidan koʻrishingiz mumkin. Jonli efirlar va muhim eʼlonlar ham shu kanalda: https://t.me/+w_iepGT3xt1lMDNk. Reyting ballari faqat platformada oxirigacha koʻrilgan dars uchun beriladi (+20), kanalda koʻrilgan dars ballga qoʻshilmaydi.$kb$,
   array[$kb$https://t.me/+w_iepGT3xt1lMDNk$kb$, $kb$https://t.me/c/3985484439/7$kb$]::text[], $kb$approved$kb$, true),
  ($kb$module-release-schedule$kb$, $kb$course_logistics$kb$, $kb$Keyingi modul qachon ochiladi?$kb$,
   array[$kb$Assalomu aleykum 2-module qachon ochiladi Bugun qanaqadur vazifa topshirishimiz kerek boladimi ?$kb$, $kb$#savol 2чи модул качон очиладии$kb$, $kb$Menda yangi modul ochilmayapti$kb$, $kb$#savol Ertaga 2-modul darslari ochilgandan keyin darslar har kuni bo'ladimi yoki kun orami?$kb$, $kb$#savol ustoz dushanbadan yengi mavzudagi darsla boshlanadimi$kb$, $kb$Янги модуль дарс Хар хафта битта очиладия шунда?$kb$]::text[],
   $kb$Challenge 5 ta asosiy modul va bonus moduldan (AI bilan multfilm) iborat, yangi modul taxminan haftada bir marta ochiladi. Modul hammaga bir vaqtda ochiladi va bu «MUHIM EʼLONLAR»da hamda darsliklar kanalida eʼlon qilinadi. Eʼlon chiqqan boʻlsa-yu modul koʻrinmasa, ilovani yopib qayta oching. Modul ochilguncha joriy modul darslarini takrorlang va uyga vazifasini topshirib qoʻying.$kb$,
   '{}'::text[], $kb$approved$kb$, true),
  ($kb$live-lessons-and-recordings$kb$, $kb$course_logistics$kb$, $kb$Jonli dars / Zoom qachon? Yozuvi (zapisi) tashlanadimi?$kb$,
   array[$kb$#savol Jonli efir qachon bo'ladi?$kb$, $kb$#savol ustoz zoom boshlanishiga yaqin linkini tashab berishadimi$kb$, $kb$Nobodo jonli darsda tóliq ótiromagan taqdirimizda jonli darsni zapisiyam tawab beriladimi? Bollani uxlatadigan vaqtga tóri keptide🙈$kb$, $kb$#savol Кечеги зоомда боган дарс сохранить боганми корсам боладими хозир$kb$, $kb$Менга иш вактига тугри келди афсус катнаша олмадим видео чат запси борми$kb$, $kb$Kechagi dars zapis boganmi?$kb$]::text[],
   $kb$Jonli darslar va master-klasslar (Zoom yoki YouTube efir) odatda kechqurun soat 21:00 da boʻladi. Kunduzi oʻtkazilmaydi, chunki ishlaydigan oʻquvchilar bor. Havola efirdan oldin guruhga va darsliklar kanaliga tashlanadi. Qatnasha olmasangiz, yozuvi keyinroq asosiy darsliklar kanaliga joylanadi. Kurator bilan oʻtadigan kichik savol-javob chatlari esa har doim ham yozib olinmaydi.$kb$,
   '{}'::text[], $kb$draft$kb$, true),
  ($kb$homework-how-to-submit$kb$, $kb$platform_usage$kb$, $kb$Uyga vazifani qayerga va qanday topshiraman?$kb$,
   array[$kb$Shunga toʻliqroq javob berolasizmi Bu vazifani qaerda topshiraman$kb$, $kb$Uyga vazifa tashagandan keyin Modul tanglang divoti qaysi biri tanlanadi$kb$, $kb$#savol сайтга уйга вазифа жойласек уйга вазифа дган болимга жойлашимиз шартмасми$kb$, $kb$Assalomu alaykum Uyga vazifani joylamoqchi bólsam uyga vazifa joyga jónatilmayabdi$kb$, $kb$#savol ustoz Korib Bogan bosamam ochilmadi uyga vazifa$kb$, $kb$Uyerga xam uy vazifa xam instagram vazifa xammasini tashlayveraymi Vazifa degan joyga$kb$]::text[],
   $kb$Uyga vazifani bot orqali topshirasiz: «🚀 Ilovani ochish»ni bosing va ilovadagi uyga vazifa boʻlimidan tegishli modulni (M1, M2 …) tanlab yuklang. Rasm va fayllar (masalan, PDF) ilovaning oʻzida yuklanadi; video vazifa esa guruhdagi uyga vazifa boʻlimiga (topic) yuboriladi. Faqat vazifaning oʻzini yuboring. Topshirish tartibi «MUHIM EʼLONLAR»dagi video qoʻllanmada koʻrsatilgan.$kb$,
   '{}'::text[], $kb$approved$kb$, false),
  ($kb$homework-resubmit$kb$, $kb$platform_usage$kb$, $kb$Uyga vazifani qayta topshirsam boʻladimi?$kb$,
   array[$kb$Uyga vazifani qaytadan topshirmoqchi bo'lsak tartibi qanday bo'ladi shu guruhga yangi skrin tashab vazifani belgilab ketamizmi$kb$, $kb$Ассалому алайкум, бир вазифа бўйича бир неча марта топшириш мумкинми, шунда баллар яна қўшиладими$kb$, $kb$#savol ustoz uyga vazifamiz 8 bal olibdi shuni qayta topshirsak buladimi 10 bal olish uchun$kb$, $kb$Man adashib rasm boshqa tashlavoribman oʻchirishni iloji bormi😔$kb$, $kb$Ассалому алекум, ман билмасдан сўраш учун ташаган оасмларимни бот баҳолаб қўйди нима қисам бўлади?$kb$]::text[],
   $kb$Ha, mumkin. Ilovadagi uyga vazifa boʻlimida vazifangizni oching, «Qayta yuklash» tugmasini bosing va yangi variantni yuboring. Kurator yangi variantni baholaguncha oldingi bahongiz saqlanib turadi. Adashib boshqa fayl yuborgan boʻlsangiz ham shu yoʻl bilan almashtirasiz.$kb$,
   '{}'::text[], $kb$approved$kb$, false),
  ($kb$homework-deadline$kb$, $kb$course_logistics$kb$, $kb$Uyga vazifani qachongacha topshirish kerak?$kb$,
   array[$kb$Vazifalarni qachongacha topshirishimiz kere$kb$, $kb$#savol uyga vazifani hafta oxirigacha qilsak bo'ladimi$kb$, $kb$Uyga vazifa muddati qachongacha$kb$, $kb$2модули качонгача тугатиш кере$kb$, $kb$Ассалому алейкум #савол Биринчи дарсни вазифасини топшириш охирги куни качон? Хали чат GPD ни пуллик версияни олмадим$kb$]::text[],
   $kb$Har bir modulning uyga vazifasini oʻsha hafta ichida, keyingi modul ochilguncha topshirish tavsiya etiladi. Kechikkan vazifani ham challenge davomida (5 hafta ichida) topshirish mumkin, lekin oʻz vaqtida topshirgan maʼqul. Esda tuting: 5 ta modulning birortasi boʻyicha uyga vazifa topshirilmasa, sertifikat berilmaydi.$kb$,
   '{}'::text[], $kb$draft$kb$, true),
  ($kb$module-1-homework-chatgpt-project$kb$, $kb$course_logistics$kb$, $kb$1-modul uyga vazifasi nima va qanday skrinshot yuboriladi?$kb$,
   array[$kb$#savol Assalomu alaykum ustoz quyida rasm tashlayman unda uyga vazifa turlari haqida so'ralgan shu haqida ma'lumot bering. Uyga vazifa faqat proyekt yaratishmi yoki men tushunmay qolgan joylari bormi$kb$, $kb$Oldin proekt tayyorlab olish kkmi xuddi darsda tushuntirilgandek?$kb$, $kb$Bitta narsaga tushunmayapman vazifalar hammasini 4 ta darsnikini shu joyda bitta qilib skrin tashimizmi yoki har dars niki alohida mi$kb$, $kb$қабул қилинди девотти, проектни очиб туриб расмга олиб ташлаш кереми?$kb$, $kb$Проектни тайёрдаганимиздан кейин шу жойига куямизми "редактировать инструкции" ? Илитимос айтиб юборинг.$kb$]::text[],
   $kb$1-modulda bitta asosiy vazifa bor: 4 ta darsni toʻliq koʻrib, ChatGPT'da oʻz sohangiz uchun Proyekt (loyiha mutaxassisi) yaratish, xuddi 1.3-darsda koʻrsatilgandek. Botga ChatGPT'ning Proyektlar boʻlimida proyektingiz koʻrinib turgan skrinshotni va instruksiya («Instructions») yozilgan oynaning skrinshotini yuborasiz. Oddiy chat yozishmasining skrinshoti yetmaydi, chunki undan proyekt yaratilganini bilib boʻlmaydi. 1-modul boʻyicha qilgan boshqa ishlaringizni NETWORKING chatiga tashlang.$kb$,
   '{}'::text[], $kb$approved$kb$, true),
  ($kb$module-2-homework-brand-images$kb$, $kb$course_logistics$kb$, $kb$2-modul uyga vazifasi (7SABER brend DNK'si va reklama rasmlari) qanday bajariladi?$kb$,
   array[$kb$#савол уйга вазифа нима 2- модульдан, факат расим килишми?$kb$, $kb$Uyga berilgaan vazifa shunda 7 Saber brenga asoslanib rasm yaratish boldimi??$kb$, $kb$Assalomaleykum 2 chi modulda faqat 2 ta vazifa berildimi brend dnk si va shu dnk asosida reklamniy rasmlar tayorlash shunaqami yoki yana vazifa bormidi$kb$, $kb$#savol 7 saberdan uyga vazifadagi 6ta rasmni bir xil personaj qilish kerakmidi? Chunki har xil personajda qilayotganlar ham borda$kb$, $kb$Ассалому алейкум, бу расимла 7SABER инстаграмидан олинганку, узлари кимаганлаку$kb$]::text[],
   $kb$2-modul uyga vazifasi ikki qismdan iborat: 1) 7SABER brendining DNK'si (PDF), 2) shu DNK asosida brend uchun reklama rasmlari seriyasi. Rasmlarni kollaj qilib emas, har birini alohida tayyorlang. Bitta mahsulotni bitta atmosferada turli rakurs va pozalarda, bir xil model va bir xil oʻlchamda (masalan, post uchun 4:5, Reels uchun 9:16) qiling. Brend rasmlarini 1:1 koʻchirmang: ulardan ilhom olib, brend ruhida oʻz gʻoyangizni qoʻshing. Ikkala qismni bot orqali uyga vazifaga (M2 ni tanlab) yuborasiz.$kb$,
   '{}'::text[], $kb$approved$kb$, true),
  ($kb$extra-tasks-schedule$kb$, $kb$course_logistics$kb$, $kb$Qoʻshimcha (kunlik) vazifalar qachon chiqadi va qachongacha topshiriladi?$kb$,
   array[$kb$кунлик вазифалар качон берилади ва ким томонидан$kb$, $kb$#Savol ustoz bugungi vazifasi chiqmadimi$kb$, $kb$Топширини эртага берсак буадими$kb$, $kb$#savol kunlik vazifalarni qachongacha topshiramiz? Qo'shimcha vazifani topshirdim muddati ertagacha ekan, lekin asosiy vazifalarnikichi?$kb$, $kb$Кунлик вазифа бугун бормиди курмабман ... кунлик вазифаларни кайердан топсам булади куп чатлар езилса курмай колдими$kb$, $kb$#savol Қўшимча вазифани қаерга юклаш кере эди. Бот да тополмаяпман юклидиган жойи. Этворин илтимос$kb$]::text[],
   $kb$Qoʻshimcha vazifalar (avval «kunlik vazifa» deb atalgan) endi har kuni emas, haftada uch marta chiqadi: dushanba, chorshanba va juma kunlari soat 09:00 da. Har bir vazifani keyingi kun soat 23:59 gacha topshirish kerak. Nimani va qayerga yuborish vazifa postining oʻzida va asosiy darsliklar kanalidagi qoʻllanmada yozilgan, shuning uchun postni diqqat bilan oʻqing. Qoʻshimcha vazifalar modul darslariga bogʻliq emas va qoʻshimcha ball beradi; uyga vazifa esa alohida, modul boʻyicha topshiriladi.$kb$,
   '{}'::text[], $kb$retired$kb$, true),
  ($kb$instagram-task-how-to-submit$kb$, $kb$platform_usage$kb$, $kb$Instagram vazifasi: nimani joylayman va qanday isbot yuboraman?$kb$,
   array[$kb$Assalomu alaykum. Instagram vazifasi deb yozilganku. Bu instagramda storisga qo'yib otmetka qilishmi?$kb$, $kb$Assalom aleykum, hurmatli kuratorimiz! Instagramdagi storis o'zi yetadimi, otmetka qilingani, yoki qatgadir yuklash kk mi ssilkasini$kb$, $kb$#savol Instagram saxifasida belgilangan screenshot ni qayerga yuklash kerak$kb$, $kb$2 ta video reelsda belgilaganman lekin baho olganim yuq$kb$, $kb$Инстаграмда отметка қилинган пост учун баллни қаердан кўрса бўлади?$kb$, $kb$Энди хар бир кунлик вазифа инстаграм очиб унга куйиб бориб уни .students белгилаб кетишимиз кереми ? Шу жойини узимизни тилда тулик тшунтириб беринг$kb$]::text[],
   $kb$Instagram vazifasida ishingizni (post, karusel, Reels yoki story) oʻz Instagram sahifangizga joylaysiz va skrinshotini bot orqali qoʻshimcha vazifa sifatida yuborasiz. Skrinshotda Instagram username'ingiz aniq koʻrinib tursin, u botga saqlangan Instagram username'ingiz bilan bir xil boʻlishi kerak. Ball bot tomonidan avtomatik qoʻyiladi va uni mini ilovada koʻrasiz. Batafsil tartib asosiy darsliklar kanalidagi qoʻllanmada koʻrsatilgan.$kb$,
   array[$kb$https://www.instagram.com/aicreators.students$kb$]::text[], $kb$retired$kb$, true),
  ($kb$connect-instagram-to-bot$kb$, $kb$platform_usage$kb$, $kb$Instagram akkauntimni botga qanday ulayman?$kb$,
   array[$kb$Instagram username qanaqa ulash kere botga?$kb$, $kb$#savol Ustoz sizga savolim bor nimaga Ai bot ilovasi instagram usernamga ulanmayapti?$kb$, $kb$#savol Инстаграм аккаунтини кушдим ботда. Лекин телеграм аккаунтим хам инстаграм аккаунтим хам номи бир хил. Кушилган ссылка инстаграмгамас телеграм профильга кириб кетвотти.$kb$, $kb$Ман инстаграмни уломяпман, езганимга кирсам умуман бошка профил курсатвоти$kb$, $kb$#savol meni akkauntim to'g'rimi @ qoyganim bn o'chib ketyapti elektron pochta degandayam yozilmayapti$kb$]::text[],
   $kb$Botda «Instagram qoʻshish» tugmasini bosing, Instagram profilingiz havolasini nusxalab, username soʻralgan joyga yuboring. Agar havola Instagram oʻrniga Telegram profilingizni ochsa, platforma ichida Instagram username'ingizni qoʻlda yozing. Baribir ulanmasa, «MUHIM EʼLONLAR»dagi qoʻllanmani koʻring yoki ekran skrinshoti bilan «#savol» deb kuratorga yozing.$kb$,
   '{}'::text[], $kb$retired$kb$, true),
  ($kb$instagram-account-needed$kb$, $kb$course_logistics$kb$, $kb$Instagram sahifa shartmi? Yangisini ochaymi yoki borini ishlataymi?$kb$,
   array[$kb$мени Инстаграм и йок нима кли куратор????$kb$, $kb$Yangi instagram ochaylik mi uyga vazifalar uchun?$kb$, $kb$#savol ustoz bunda Instagram uchun alohida profil ochish kerak emasmi, o'zimiz yuritayotgan profil ni davom ettirsak ham bo'ladimi$kb$, $kb$#САВОЛ Инстаграмимни бошка йуналиш буйича очса буладими ? 1 чи вазифада укитувчилик деганман. Шуни давом эттиришим керакми ёки?$kb$, $kb$#savol Instagram yoʻq boʻlsa ochish kerakmi$kb$]::text[],
   $kb$Instagram sahifa tavsiya etiladi, chunki ishlaringizni joylab borasiz va keyinchalik u portfolio boʻladi. Yangi sahifa ochish yoki mavjud sahifangizni davom ettirish ixtiyoriy. Kelajakda professional akkaunt va portfolio sifatida ishlatishni hisobga olib tanlang. Sahifa yoʻnalishini (AI yoki oʻz sohangiz) ham oʻzingiz belgilaysiz.$kb$,
   '{}'::text[], $kb$approved$kb$, false),
  ($kb$points-and-rating-system$kb$, $kb$course_logistics$kb$, $kb$Ball va reyting qanday hisoblanadi? Nega boshqalarda ball koʻp?$kb$,
   array[$kb$Vidyolarni kursez 10 baldan berarkan uy vazifa qisez 10 balgacha baholanadi maksimal 135 ball bularkan lekin ortiqcha 145 ball qayerdan kelib chiqdi tushunarsiz$kb$, $kb$#savol Borsa hamma vazifalarni bajarsam ham balım maksimal emas, nima qilsa bo'ladi?$kb$, $kb$Хайрли кеч яхшилар, баллар нимани ҳисобига кўтарилади, қолганларникини кўрсам 180 баллга чиқибди, маники 147 да турибдию, нима қилсам ошади балларим$kb$, $kb$#savol o'zgartirish kiritilgan ballarga tushunmadim. Uyga vazifaga 15 ball deyilgan yana tagida nimaga vazifa deb 9-10 ball. +25 ball deyilgan.$kb$, $kb$Ustoz botni reytinglar bo’limiga 4-5 kun oldin kirganimda 147-o’rni dasiz dib ko’rsatgandi. Shunda umumiy 4 ta guruh ishtirokchilari orasida hisoblabgan o’rinmi bu?$kb$, $kb$Savol: Botda Videoni tezlashtirib korish balga tasir qiladimi?$kb$]::text[],
   $kb$8-oktabrdan boshlab reytingga ball faqat darslar va uyga vazifalar uchun qoʻshiladi: platformada darsni oxirigacha koʻrish — +20 ball, uyga vazifa topshirish — +15 ball, vazifaga 9 yoki 10 baho — yana +25 ball. Shu sanagacha yigʻilgan barcha ballaringiz saqlanib qoladi. Qoʻshimcha vazifalar, Instagram va guruhdagi savol-javob uchun endi ball berilmaydi. Ballaringizni botdagi «👤 Profil» boʻlimida va ilovaning bosh sahifasida koʻrasiz.$kb$,
   array[$kb$https://t.me/c/4390902020/123/1126$kb$]::text[], $kb$approved$kb$, true),
  ($kb$homework-grading-feedback$kb$, $kb$course_logistics$kb$, $kb$Uyga vazifani kim, qachon baholaydi va izohni qayerda koʻraman?$kb$,
   array[$kb$Assalomu alaykum. Vazifa yuborilgandan kn xato-kamchliklarini aytasizlarmi?$kb$, $kb$Qachon korib etvorasila$kb$, $kb$#savol лекин буёда уйга вазифа болими борлиги учун соравоман буёга ташалмидими шунда факат платформага жойланса болдиде торими ?кейин кориб чканздан кейн озиз фидбек берасми$kb$, $kb$Uyga vazifala qachon baxolanadi?$kb$, $kb$Ассалому алейкум #САВОЛ кечаги кунлик вазифам Кабул килинди дейилади, лекин бахоланмади. Нега?$kb$]::text[],
   $kb$Uyga vazifani guruhingiz kuratori 10 ballik tizimda baholaydi: 9–10 aʼlo, 7–8 yaxshi, 5–6 oʻrtacha, 3–4 qayta ishlash kerak. Baho qoʻyilgach, bot sizga baho va kurator izohini shaxsiy xabarda yuboradi, ularni ilovadagi uyga vazifa boʻlimida ham koʻrasiz. Izoh faqat sizga koʻrinadi. 9 yoki 10 baho reytingga yana +25 ball qoʻshadi.$kb$,
