update public.support_kb set approved_at = now()
 where status = 'approved' and approved_at is null;

insert into public.admin_actions (actor_user_id, action, details)
select null, 'support_kb_seeded', jsonb_build_object(
  'migration', '20261011091800', 'approved', (select count(*) from public.support_kb where status = 'approved'),
  'draft', (select count(*) from public.support_kb where status = 'draft'),
  'retired', (select count(*) from public.support_kb where status = 'retired'), 'by', 'owner chat approval 2026-10-11')
where not exists (select 1 from public.admin_actions where action = 'support_kb_seeded');
